
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_tw4_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_tw4", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([9.446417479922312e+01, 9.080431314131364e+01, 8.579952991643168e+01, 7.910489179403565e+01, 7.042792929024100e+01, 5.967606107423598e+01, 4.717506389301996e+01, 3.388259343437583e+01, 2.138767127949624e+01, 1.142407657496758e+01, 5.057880473320533e+00, 2.542430007210479e+00, 1.914009363796350e+00, 1.274183935751670e+00, 6.457726720387307e-01, 2.431021008964402e-01, 6.156739911789553e-02, 7.662980794093724e-03, 3.555081782191292e-04, 4.460696979808903e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


